            records.append(
                RenameRecord(
                    old_path=str(path),
                    new_path=str(target),
                    start_local=start_dt.isoformat(),
                    end_local=end_dt.isoformat(),
                    timestamp_source=source,
                    message_count=count,
                    status=status,
                    warnings=warnings,
