            )
        except (OSError, UnicodeError, json.JSONDecodeError, ValueError) as exc:
            records.append(
                RenameRecord(
                    old_path=str(path),
                    new_path=None,
                    start_local=None,
                    end_local=None,
                    timestamp_source=None,
                    message_count=0,
                    status="skipped",
                    warnings=[str(exc)],
