import textwrap, pathlib

script = r'''#!/usr/bin/env python3
"""
date_archive_artifacts.py

Conservative date/provenance scanner for the SAT main archive.

Purpose
-------
Main-archive files are heterogeneous: ChatGPT JSON exports, pasted transcripts,
notes, Markdown, generated summaries, PDFs, and files whose only reliable date
is when they entered Git. This tool does NOT treat every detected date as a
creation date.

It inventories date evidence and writes an auditable manifest. Renaming is
optional and deliberately conservative.

Evidence classes
----------------
1. conversation_message_range
   Native ChatGPT JSON message timestamps; strongest automatic evidence for
   conversation span.

2. explicit_content_date
   Dates parsed from text/Markdown content. These may be message dates, section
   dates, pasted source dates, or references, so they are evidence rather than
   automatically "document creation dates."

3. filename_date
   Existing date notation in the filename.

4. git_first_added
   Earliest Git commit in which the path appears. This is an ARCHIVE/LOGGING
   date unless independently corroborated; it is never silently promoted to a
   content-creation date.

5. filesystem_mtime
   Fallback only when Git history is unavailable. Weak evidence.

Default behavior
----------------
Dry-run inventory only. Produces JSONL + CSV manifests and does not rename files.

Example:
    python tools/date_archive_artifacts.py --root .

Optional conservative rename:
    python tools/date_archive_artifacts.py --root . --apply-renames

Only files with a high-confidence native conversation range are renamed by
default. Use --rename-explicit-content-dates to allow text-derived ranges too.
Git-only/archive dates are NEVER used for automatic renaming.
"""

from __future__ import annotations

import argparse
import csv
import json
import os
import re
import subprocess
from dataclasses import asdict, dataclass, field
from datetime import datetime, timezone
from pathlib import Path
from typing import Any, Iterable
from zoneinfo import ZoneInfo

DEFAULT_TZ = "America/New_York"
TEXT_SUFFIXES = {".txt", ".md", ".markdown", ".csv", ".tsv", ".html", ".htm", ".json"}
SKIP_DIR_NAMES = {".git", "__pycache__", ".pytest_cache", ".mypy_cache", ".venv", "venv"}
SKIP_PREFIXES = (".[", "..[")  # control layers are skipped unless --include-control
DATE_PREFIX_RE = re.compile(r"^\d{2}\.\d{2}\.\d{2}•(?:\d{2}\.\d{2}\.\d{2}•)?")

# Text date patterns. Intentionally conservative: four-digit years are preferred.
TEXT_DATE_PATTERNS = [
    # 2026-09-09 / 2026.09.09
    re.compile(r"(?<!\d)(20\d{2})[-.](0?[1-9]|1[0-2])[-.](0?[1-9]|[12]\d|3[01])(?!\d)"),
    # 09/09/2026 or 9-9-2026
    re.compile(r"(?<!\d)(0?[1-9]|1[0-2])[/-](0?[1-9]|[12]\d|3[01])[/-](20\d{2})(?!\d)"),
]

MONTHS = {
    "jan": 1, "january": 1, "feb": 2, "february": 2, "mar": 3, "march": 3,
    "apr": 4, "april": 4, "may": 5, "jun": 6, "june": 6, "jul": 7, "july": 7,
    "aug": 8, "august": 8, "sep": 9, "sept": 9, "september": 9,
    "oct": 10, "october": 10, "nov": 11, "november": 11,
    "dec": 12, "december": 12,
}
MONTH_NAME_RE = re.compile(
    r"(?i)(?<![A-Za-z])("
    + "|".join(sorted(MONTHS, key=len, reverse=True))
    + r")\.?\s+([0-3]?\d)(?:st|nd|rd|th)?[,]?\s+(20\d{2})(?!\d)"
)
DAY_MONTH_RE = re.compile(
    r"(?i)(?<!\d)([0-3]?\d)\s+("
    + "|".join(sorted(MONTHS, key=len, reverse=True))
    + r")\.?[,]?\s+(20\d{2})(?!\d)"
)

# Existing filename conventions seen/anticipated in the archive.
FILENAME_PATTERNS = [
    re.compile(r"(?<!\d)(20\d{2})[-._](0?[1-9]|1[0-2])[-._](0?[1-9]|[12]\d|3[01])(?!\d)"),
    re.compile(r"(?<!\d)(\d{2})\.(0?[1-9]|1[0-2])\.(0?[1-9]|[12]\d|3[01])(?!\d)"),
]

HUMAN_ROLES = {"user", "assistant"}

@dataclass
class DateEvidence:
    kind: str
    start: str | None
    end: str | None
    confidence: str
    note: str = ""

@dataclass
class Record:
    path: str
    suffix: str
    size: int
    selected_start: str | None = None
    selected_end: str | None = None
    selected_basis: str | None = None
    selected_confidence: str | None = None
    rename_target: str | None = None
    rename_status: str = "not-planned"
    evidence: list[DateEvidence] = field(default_factory=list)
    warnings: list[str] = field(default_factory=list)

def iso_date(dt: datetime) -> str:
    return dt.date().isoformat()

def safe_dt(year: int, month: int, day: int, tz: ZoneInfo) -> datetime | None:
    try:
        return datetime(year, month, day, tzinfo=tz)
    except ValueError:
        return None

def numeric_timestamp(value: Any) -> float | None:
    if isinstance(value, (int, float)) and value > 0:
        return float(value)
    if isinstance(value, str):
        try:
            v = float(value)
            return v if v > 0 else None
        except ValueError:
            return None
    return None

def active_node_ids(data: dict[str, Any], mapping: dict[str, Any]) -> set[str]:
    current = data.get("current_node")
    if not isinstance(current, str) or current not in mapping:
        return set(mapping)
    out: set[str] = set()
    node_id: str | None = current
    while node_id and node_id in mapping and node_id not in out:
        out.add(node_id)
        parent = mapping[node_id].get("parent")
        node_id = parent if isinstance(parent, str) else None
    return out

def conversation_range(path: Path, tz: ZoneInfo) -> DateEvidence | None:
    if path.suffix.lower() != ".json":
        return None
    try:
        data = json.loads(path.read_text(encoding="utf-8-sig"))
    except Exception:
        return None
    if isinstance(data, list) and len(data) == 1 and isinstance(data[0], dict):
        data = data[0]
    if not isinstance(data, dict):
        return None
    mapping = data.get("mapping")
    if not isinstance(mapping, dict):
        return None

    stamps: list[float] = []
    human_count = 0
    for node_id in active_node_ids(data, mapping):
        node = mapping.get(node_id)
        if not isinstance(node, dict):
            continue
        message = node.get("message")
        if not isinstance(message, dict):
            continue
        author = message.get("author")
        role = author.get("role") if isinstance(author, dict) else None
        if role not in HUMAN_ROLES:
            continue
        human_count += 1
        stamp = numeric_timestamp(message.get("create_time")) or numeric_timestamp(message.get("update_time"))
        if stamp is not None:
            stamps.append(stamp)
    if not stamps:
        return None

    start = datetime.fromtimestamp(min(stamps), timezone.utc).astimezone(tz)
    end = datetime.fromtimestamp(max(stamps), timezone.utc).astimezone(tz)
    note = f"{len(stamps)}/{human_count} user/assistant messages had usable timestamps"
    return DateEvidence("conversation_message_range", iso_date(start), iso_date(end), "high", note)

def parse_text_dates(text: str, tz: ZoneInfo) -> list[datetime]:
    dates: list[datetime] = []

    for m in TEXT_DATE_PATTERNS[0].finditer(text):
        dt = safe_dt(int(m.group(1)), int(m.group(2)), int(m.group(3)), tz)
        if dt: dates.append(dt)

    for m in TEXT_DATE_PATTERNS[1].finditer(text):
        dt = safe_dt(int(m.group(3)), int(m.group(1)), int(m.group(2)), tz)
        if dt: dates.append(dt)

    for m in MONTH_NAME_RE.finditer(text):
        dt = safe_dt(int(m.group(3)), MONTHS[m.group(1).lower().rstrip(".")], int(m.group(2)), tz)
        if dt: dates.append(dt)

    for m in DAY_MONTH_RE.finditer(text):
        dt = safe_dt(int(m.group(3)), MONTHS[m.group(2).lower().rstrip(".")], int(m.group(1)), tz)
        if dt: dates.append(dt)

    # De-duplicate.
    uniq = {d.date(): d for d in dates}
    return [uniq[k] for k in sorted(uniq)]

def text_date_evidence(path: Path, tz: ZoneInfo, max_bytes: int) -> DateEvidence | None:
    if path.suffix.lower() not in TEXT_SUFFIXES or path.suffix.lower() == ".json":
        return None
    try:
        if path.stat().st_size > max_bytes:
            with path.open("r", encoding="utf-8-sig", errors="replace") as f:
                # Date scan uses head + tail for very large files.
                head = f.read(max_bytes // 2)
                f.seek(max(0, path.stat().st_size - max_bytes // 2))
                tail = f.read(max_bytes // 2)
                text = head + "\n" + tail
            note_extra = "sampled head+tail only"
        else:
            text = path.read_text(encoding="utf-8-sig", errors="replace")
            note_extra = "full text scanned"
    except OSError:
        return None

    dates = parse_text_dates(text, tz)
    if not dates:
        return None
    # Content dates may be references, not document dates: medium confidence maximum.
    return DateEvidence(
        "explicit_content_date",
        iso_date(dates[0]),
        iso_date(dates[-1]),
        "medium",
        f"{len(dates)} distinct explicit date(s); {note_extra}; requires contextual review",
    )

def filename_date_evidence(path: Path, tz: ZoneInfo) -> DateEvidence | None:
    name = path.name
    found: list[datetime] = []
    for i, pat in enumerate(FILENAME_PATTERNS):
        for m in pat.finditer(name):
            if i == 0:
                year, month, day = map(int, m.groups())
            else:
                yy, month, day = map(int, m.groups())
                year = 2000 + yy
            dt = safe_dt(year, month, day, tz)
            if dt: found.append(dt)
    if not found:
        return None
    found.sort()
    return DateEvidence(
        "filename_date",
        iso_date(found[0]),
        iso_date(found[-1]),
        "medium",
        "date notation already present in filename; semantic meaning unknown",
    )

def run_git(repo_root: Path, args: list[str]) -> str | None:
    try:
        cp = subprocess.run(
            ["git", "-C", str(repo_root), *args],
            stdout=subprocess.PIPE, stderr=subprocess.DEVNULL,
            text=True, check=False, encoding="utf-8", errors="replace",
        )
    except OSError:
        return None
    return cp.stdout.strip() if cp.returncode == 0 and cp.stdout.strip() else None

def git_first_added(path: Path, repo_root: Path, tz: ZoneInfo) -> DateEvidence | None:
    try:
        rel = path.relative_to(repo_root).as_posix()
    except ValueError:
        return None

    # --diff-filter=A is the best available proxy for "entered the archive at this path."
    out = run_git(repo_root, [
        "log", "--follow", "--diff-filter=A", "--format=%aI", "--reverse", "--", rel
    ])
    if not out:
        # fallback: earliest commit touching the path
        out = run_git(repo_root, ["log", "--follow", "--format=%aI", "--reverse", "--", rel])
    if not out:
        return None
    first = out.splitlines()[0].strip()
    try:
        dt = datetime.fromisoformat(first.replace("Z", "+00:00")).astimezone(tz)
    except ValueError:
        return None
    return DateEvidence(
        "git_first_added",
        iso_date(dt),
        iso_date(dt),
        "medium",
        "archive/logging date from Git history; NOT assumed to be content-creation date",
    )

def filesystem_mtime(path: Path, tz: ZoneInfo) -> DateEvidence | None:
    try:
        dt = datetime.fromtimestamp(path.stat().st_mtime, timezone.utc).astimezone(tz)
    except OSError:
        return None
    return DateEvidence(
        "filesystem_mtime", iso_date(dt), iso_date(dt), "low",
        "fallback only; may reflect checkout/copy time"
    )

def should_skip(path: Path, root: Path, include_control: bool) -> bool:
    rel_parts = path.relative_to(root).parts
    for part in rel_parts[:-1]:
        if part in SKIP_DIR_NAMES:
            return True
        if not include_control and part.startswith(SKIP_PREFIXES):
            return True
    return False

def candidates(root: Path, include_control: bool) -> Iterable[Path]:
    for path in root.rglob("*"):
        if not path.is_file():
            continue
